## How global styles are loaded

Look at the current page's `<head>`:

```html
<link rel='stylesheet' id='global-styles-inline-css' href='…' …>
<link rel='stylesheet' id='wp-block-supports-css' href='…' …>
<style id='global-styles-inline-css'>…</style>
```

WordPress 7.0+ emits global styles as one of:

1. An inline `<style id="global-styles-inline-css">` block (block themes).
2. An external `<link rel="stylesheet" id="wp_global_styles-css">` link
   (when the styles are committed to a post with `post_type =
   wp_global_styles`).

The reflector must handle both.

## Reference pattern

```js
// src/floating-widget/reflectors/global-styles.js — pseudocode
export async function reflectGlobalStyles( event ) {
    try {
        const fresh = await fetchFreshHead( event.affected.url );
        replaceInlineStyle( fresh, 'global-styles-inline-css' );
        replaceLinkStylesheet( fresh, 'wp_global_styles-css' );
        replaceLinkStylesheet( fresh, 'global-styles-css' );
    } catch ( err ) {
        console.warn( '[sd-ai-agent] global-styles reflector failed', err );
    }
}

async function fetchFreshHead( url ) {
    const target = url || window.location.href;
    const bust = target + ( target.includes( '?' ) ? '&' : '?' ) + '_=' + Date.now();
    const res = await fetch( bust, {
        credentials: 'same-origin',
        cache: 'no-store',
        headers: { Accept: 'text/html' },
    } );
    if ( ! res.ok ) throw new Error( `HTTP ${ res.status }` );
    return new DOMParser().parseFromString( await res.text(), 'text/html' );
}

function replaceInlineStyle( freshDoc, id ) {
    const fresh = freshDoc.getElementById( id );
    const current = document.getElementById( id );
    if ( ! fresh || ! current ) return;
    if ( fresh.tagName !== 'STYLE' ) return;
    if ( fresh.textContent === current.textContent ) return;
    current.textContent = fresh.textContent;
}

function replaceLinkStylesheet( freshDoc, id ) {
    const fresh = freshDoc.getElementById( id );
    const current = document.getElementById( id );
    if ( ! fresh || ! current ) return;
    if ( fresh.tagName !== 'LINK' ) return;
    const freshHref = fresh.getAttribute( 'href' );
    if ( ! freshHref || freshHref === current.getAttribute( 'href' ) ) return;
    // Swap href with cache-bust to force a fresh fetch.
    const url = new URL( freshHref, window.location.origin );
    url.searchParams.set( '_', String( Date.now() ) );
    current.setAttribute( 'href', url.toString() );
}
```

